#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PYTHON_BIN="${PYTHON_BIN:-/common/users/wq50/envs/pace/bin/python}"

export DOWNLOAD_JOBS=6
export DOWNLOAD_N_PROCESSES=4

export BASE_DATA_DIR="${BASE_DATA_DIR:-/research/projects/mllab/WSI/TCGA_features}"
export INDEX_JSON="${INDEX_JSON:-$ROOT_DIR/metadata/indexes/manifest_index.json}"
export REUSE_COORDS_BASE="${REUSE_COORDS_BASE:-/research/projects/mllab/WSI/TCGA_features}"

export ONLY_PROJECTS="${ONLY_PROJECTS:-}"
export SKIP_PROJECTS="${SKIP_PROJECTS:-}"
export STRICT_MATCH="${STRICT_MATCH:-0}"
export AUTO_PROCESS_MISMATCH="${AUTO_PROCESS_MISMATCH:-1}"
export CONTINUE_ON_ERROR="${CONTINUE_ON_ERROR:-1}"
export CLEANUP_SLIDES_AFTER_BOTH="${CLEANUP_SLIDES_AFTER_BOTH:-1}"

export VIRCHOW_DATASET_ID="${VIRCHOW_DATASET_ID:-w8yi/tcga-wsi-virchow2-features}"
export GIGAPATH_DATASET_ID="${GIGAPATH_DATASET_ID:-w8yi/tcga-wsi-gigapath-features}"
export VIRCHOW_FEATURES_SUBDIR="${VIRCHOW_FEATURES_SUBDIR:-features_virchow2}"
export GIGAPATH_FEATURES_SUBDIR="${GIGAPATH_FEATURES_SUBDIR:-features_gigapath}"
export VIRCHOW_UPLOAD_SUBDIR="${VIRCHOW_UPLOAD_SUBDIR:-$VIRCHOW_FEATURES_SUBDIR}"
export GIGAPATH_UPLOAD_SUBDIR="${GIGAPATH_UPLOAD_SUBDIR:-$GIGAPATH_FEATURES_SUBDIR}"

export VIRCHOW_AUTO_UPLOAD="${VIRCHOW_AUTO_UPLOAD:-0}"
export GIGAPATH_AUTO_UPLOAD="${GIGAPATH_AUTO_UPLOAD:-0}"
export VIRCHOW_UPLOAD_MARKER_NAME="${VIRCHOW_UPLOAD_MARKER_NAME:-.upload_complete_virchow2}"
export GIGAPATH_UPLOAD_MARKER_NAME="${GIGAPATH_UPLOAD_MARKER_NAME:-.upload_complete_gigapath}"
export PROJECT_COMPLETE_FLAG_NAME="${PROJECT_COMPLETE_FLAG_NAME:-.seal_encode_complete}"

# Shared extraction defaults used by both per-project scripts.
export GPU_LIST="${GPU_LIST:-${CUDA_VISIBLE_DEVICES:-,3,4,5}}"
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-$GPU_LIST}"
export EXTRACT_DYNAMIC_GPU="${EXTRACT_DYNAMIC_GPU:-1}"
export PYTORCH_CUDA_ALLOC_CONF="${PYTORCH_CUDA_ALLOC_CONF:-expandable_segments:True}"
export BATCH_SIZE="${BATCH_SIZE:-3072}"
export MIN_BATCH_SIZE="${MIN_BATCH_SIZE:-8}"
export FILTER_WORKERS="${FILTER_WORKERS:-4}"
export LOADER_WORKERS="${LOADER_WORKERS:-4}"
export LOADER_PREFETCH_FACTOR="${LOADER_PREFETCH_FACTOR:-4}"
export LOADER_PIN_MEMORY="${LOADER_PIN_MEMORY:-1}"
export WRITE_RETRIES="${WRITE_RETRIES:-5}"
export UPLOAD_MODE="${UPLOAD_MODE:-standard}"
export NUM_UPLOAD_WORKERS="${NUM_UPLOAD_WORKERS:-8}"

cat <<EOF
[dual-encoder-defaults]
ROOT_DIR=$ROOT_DIR
PYTHON_BIN=$PYTHON_BIN
BASE_DATA_DIR=$BASE_DATA_DIR
INDEX_JSON=$INDEX_JSON
REUSE_COORDS_BASE=$REUSE_COORDS_BASE
ONLY_PROJECTS=${ONLY_PROJECTS:-<none>}
SKIP_PROJECTS=${SKIP_PROJECTS:-<none>}
STRICT_MATCH=$STRICT_MATCH
AUTO_PROCESS_MISMATCH=$AUTO_PROCESS_MISMATCH
CONTINUE_ON_ERROR=$CONTINUE_ON_ERROR
CLEANUP_SLIDES_AFTER_BOTH=$CLEANUP_SLIDES_AFTER_BOTH
VIRCHOW_DATASET_ID=$VIRCHOW_DATASET_ID
GIGAPATH_DATASET_ID=$GIGAPATH_DATASET_ID
VIRCHOW_FEATURES_SUBDIR=$VIRCHOW_FEATURES_SUBDIR
GIGAPATH_FEATURES_SUBDIR=$GIGAPATH_FEATURES_SUBDIR
VIRCHOW_UPLOAD_SUBDIR=$VIRCHOW_UPLOAD_SUBDIR
GIGAPATH_UPLOAD_SUBDIR=$GIGAPATH_UPLOAD_SUBDIR
VIRCHOW_AUTO_UPLOAD=$VIRCHOW_AUTO_UPLOAD
GIGAPATH_AUTO_UPLOAD=$GIGAPATH_AUTO_UPLOAD
VIRCHOW_UPLOAD_MARKER_NAME=$VIRCHOW_UPLOAD_MARKER_NAME
GIGAPATH_UPLOAD_MARKER_NAME=$GIGAPATH_UPLOAD_MARKER_NAME
PROJECT_COMPLETE_FLAG_NAME=$PROJECT_COMPLETE_FLAG_NAME
GPU_LIST=$GPU_LIST
EXTRACT_DYNAMIC_GPU=$EXTRACT_DYNAMIC_GPU
BATCH_SIZE=$BATCH_SIZE
MIN_BATCH_SIZE=$MIN_BATCH_SIZE
LOADER_WORKERS=$LOADER_WORKERS
LOADER_PREFETCH_FACTOR=$LOADER_PREFETCH_FACTOR
WRITE_RETRIES=$WRITE_RETRIES
UPLOAD_MODE=$UPLOAD_MODE
NUM_UPLOAD_WORKERS=$NUM_UPLOAD_WORKERS
PYTORCH_CUDA_ALLOC_CONF=$PYTORCH_CUDA_ALLOC_CONF
CUDA_VISIBLE_DEVICES=$CUDA_VISIBLE_DEVICES
EOF

exec "$PYTHON_BIN" \
  "$ROOT_DIR/scripts/tcga_project_pipeline/run_all_tcga_projects_virchow2_gigapath.py" \
  "$@"
